from book import Chapter
c=Chapter('10')
c.src('R54886',12,13,replacements=[('对吧？',''),('具体的思考过程就被压缩了，直接跳过这个过程，变成了肌肉神经、周围神经和中枢神经之间的配合，而不是纯粹靠大脑思考之后再去操作','许多原来需要刻意注意的步骤逐渐熟练，不必每次都重新进行同样的显性思考'),('可能就根本不需要大脑神经元再参与，肌肉记忆直接替代了它','不再需要像初学时那样逐步思索；这并不意味着大脑不再参与'),('这有点像我说的软件工程中的方式','软件工程中也可以考察一种相似的积累方式')])
c.add('''假如每次打开一份文档，都要重新推导操作系统怎样寻找文件，每次排序都要重新发明排序算法，我们几乎没有余力完成更复杂的工作。已经形成的能力之所以有价值，就是因为它可以把一段探索过程保存下来，让后来的活动从更高的位置开始。

AI 的推理也有同样的问题。探索未知步骤很有必要，但已经反复验证的过程，如果仍然每次都由模型重新猜测、重新编排，就会消耗不必要的时间，还增加走错路径的机会。冷路径与热路径的区分，正是从这里提出的。''')
c.heading('一次探索，怎样成为下一次可以使用的能力')
c.src('R54910',10,replacements=[('而我现在正在做的这些事情，其实就是在准备好这个设想所需的不同拼图模块','这些功能可以由不同模块逐步组成'),('merkle-DAG框架，用来存储人类知识DNA','Merkle-DAG 框架用来记录知识与构造关系'),('这个由AI大模型驱动的项目quick-launcher将由AI大模型处理冷路径，然后固化成热路径提高运行效率','Quick Launcher 的设想，是让 AI 处理需要探索的冷路径，再把经过检验、适合重复的部分固化成热路径'),('它将会成为','它可以成为')])
c.add('''这里的“固化”，不是把一次成功的操作机械地录下来。一次成功可能依赖某个文件位置、某个登录状态，或者某个尚未变化的界面。要让它成为能力，需要把输入、输出、适用条件与可能影响说明白，再区分哪些条件可以变化，哪些不能变化。

例如，“把这批照片整理到指定目录”包含识别、命名和写入。识别规则可以作为一种可复用知识，写入哪个目录则由这次任务决定。把路径写死，不能算得到通用能力；把所有条件都交给模型每次重想，又失去了积累。真正需要保存的，是能够在明确条件下重新使用的过程。''')
c.heading('从一个本地入口开始，把宏观任务和微观功能连接起来')
c.src('R49187',0,start='为了避免版权问题和大规模抓取数据有可能违反数据提供方规则的问题',end='经过专家与AI的评测，可以迭代成新版本。',replacements=[('将这个quick launcher限制在本地电脑/局域网空间之内，只对用户所拥有的数据进行','最初把 Quick Launcher 放在本地电脑与局域网内，先处理用户能够使用的资料'),('同时将覆盖的名词动词范围扩大到不仅仅覆盖','它所覆盖的名词和动词，不仅包括'),('初期实现中，为了避免版权问题和大规模抓取数据有可能违反数据提供方规则的问题，最初把 Quick Launcher 放在本地电脑与局域网内，先处理用户能够使用的资料；','初期实现中，'),('通过一个语义归一的核心','通过一个尽量明确语义的核心'),('这样可以做到本地资源的闪电响应','这样可以争取让本地资源更快响应'),('都要高效快捷的多','具有减少重复步骤的潜力'),('这样就很好的避免了各种版权和批量抓取的限制问题。','资料的获取仍然需要遵守相应的访问条件。'),('这个项目还可以设计一个','\n\n还可以设计一个'),('你也可以通过','参与者也可以通过')])
c.add('''宏观任务与微观功能之间，本来就存在连续的构造关系。看一份资料，需要先找到它、读取它、解释它的格式，再呈现出来；每一个步骤还可以继续拆解。统一框架的意义，是使这些步骤不必永远被封闭在互不相通的应用内部。

共享的也不只是最终结果。一个人构造出了更好的获取、转换或检查方式，其他人可以在条件相容时直接使用这项能力，而不必从头经历同样的摸索。遇到新的环境，又可以从已有结构分出新的实现，并留下它与原实现的关系。''')
c.heading('自然语言入口，不等于把所有界面都变成聊天框')
c.src('R36081',0,start='我想接下来，先将精力集中到提高这些功能的可用性上来',end='就会显示对应的GUI软件界面，',replacements=[('我想接下来，先将精力集中到提高这些功能的可用性上来','这些功能还需要有足够好的可用性'),('目前kiwiclaw的界面直接借鉴的是codex，claude code之类的基于编程项目/工作任务的智能体CLI/GUI界面','以编程项目和工作任务为中心的智能体界面，提供了一种入口'),('这个界面虽然接受的是','这类界面虽然可以接受'),('这其实就是CLI界面的简单图形化，几乎没有利用图形界面的优势','但如果只把命令行输出搬进窗口，就没有充分利用图形界面的优势'),('比如当用输入','比如当用户输入'),('同样的硬盘信息页面','同样的影片信息页面'),('“小说”，“漫画”，“音乐”甚至“AV”','“小说”“漫画”“音乐”'),('显示时下最新的影视内容，并提供在线观看或下载的选项','显示用户可以访问的影视内容，并提供相应操作'),('直接显示该影片的影视信息和在线观看以及下载的链接','直接显示该影片的信息和可用的观看方式'),('就会显示对应的GUI软件界面，','就显示相应的图形操作界面。')])
c.src('R36081',0,start='而且以上提到的各种界面',end='所有的用户界面的数据结构本质上都是merkle-DAG tree，用户可以随意切换不同的界面及其样式。',replacements=[('而且以上提到的','这些'),('所有的用户界面的数据结构本质上都是merkle-DAG tree','界面的数据结构可以按 Merkle-DAG 组织'),('随意切换','在兼容的视图之间切换')])
c.add('''这个例子所表达的，是界面应该随任务展开。当用户只说了“电影”，他可能正在选择内容；已经选定一部影片，他需要的是播放和相关资料；看完以后，他才可能愿意阅读包含剧情细节的讨论。一个固定的聊天框，很难把这些不同阶段都表达好。

与此同时，同一项功能可以有不同呈现。初学者看到少量容易理解的选项，熟悉任务的人看到更细的设置。底层任务保持明确，表现方式按需要变化。这样，个人化就不必意味着每个人都拥有一套互不兼容的内部系统。''')
c.heading('更低层的实现，为什么有时反而更慢')
c.add('''实践中出现过一个很有启发的负结果。在一份已归档的实验说明里，对固定批次的 4096 个二维坐标点进行变换，原 Python 入口约需 0.806 毫秒，而带条件检查、独立 C 进程调用、数据转换和结果恢复的完整路径约需 15.6 毫秒，慢约十九倍。

这个结果不能说成“C 运算比 Python 慢十九倍”。被测量的是整个调用过程，而不是单独的计算循环；它也没有在计时路径中遍历 Merkle-DAG 或计算 CID，所以不能直接把差距归因于内容寻址。真正暴露的问题，是任务很轻，跨边界处理却很重。

这正好说明，热路径的价值不能只靠实现语言或代码外观判断。一个计算片段更短，不等于完整任务更快；一次调用节省的工作，也可能被检查、通信和格式转换抵消。要决定是否采用新实现，需要把用户实际等待的全过程测出来。

同样，一份源码评估能够说明模块是否存在、接口怎样连接，却不能代替实际运行。早期 HotPath 评估报告明确记录了自身没有独立完成编译与运行验证的限制。把这样的限制保留下来，比把所有报告都写成“已经验证”更有助于后续研究。''',reason='根据已归档实验与静态评估材料写作；不是作者原话或本轮新运行结果')
c.heading('能力怎样在反馈中继续改变')
c.src('R48755',0,start='但是这些规则',end='应该添加哪些元素和功能？',replacements=[('但是这些规则，都是','许多语言规则主要处理'),('缺乏在编写代码,在构造代码，实践运行，获得反馈，修改代码，通过热路径的构造，不断最小化，逼近不动点的代码本身的动态进化过程的约束','而我还希望描述编写代码、实际运行、获得反馈、修改实现、积累热路径这一整套动态过程'),('也就是说现在的计算机语言只规定了什么样的代码合法可运行，但是没有关于一段程序是否在探测和构造不动点的过程中有意义有价值','程序是否合法可运行，与它是否在构造过程中提供了有意义的改进，是两个需要连接的问题'),('你觉得如果要想构造一个用于AI和人类用于对齐外部世界','如果要构造一种供 AI 和人类共同对齐外部世界'),('基于上面的范畴论和新AI世界观，你觉得应该添加哪些元素和功能？','就需要把适用条件、实际结果、比较依据与修正关系一起纳入。')])
c.add('''这样，能力库就不只是在一个地方存放许多脚本。它需要知道每项能力解决什么问题，已经在哪些条件下使用，哪里出现过失败，新的实现为什么值得取代旧的实现。旧路径也不必被抹掉：它可能在另一种设备、另一种任务规模下仍然更合适。

从反复思考到可以复用，再从复用得到新的反馈，知识开始进入可积累的实践循环。接下来，新语言与模型结构所要解决的，就是怎样让这个循环少一些不必要的解释与转换，多一些能够直接使用的明确关系。''')
c.save({'reasoning':'熟练化→冷路径探索与热路径复用→适用条件→宏微观任务→共享能力→界面与语义分离→完整成本负结果→动态改进','examples':['驾驶技能','照片整理','表达式与列表排序','电影观看前后界面','4096点跨进程负结果'],'objections':['录制一次就能通用吗','聊天框等于智能界面吗','C实现必然快吗','静态评估能证明运行吗'],'evidence_refs':['R54235','HOTPATH-REPORT'],'voice':'Quick Launcher与KiwiClaw长段保留；研究结果用有来源的编辑叙述，不计为作者原话','status':'初校；未声称本轮重跑历史实验或当前产品状态'})
